public List<StaticParam> recurOnListOfStaticParam(List<StaticParam> that) {
    java.util.ArrayList<StaticParam> accum = new java.util.ArrayList<StaticParam>();
    boolean unchanged = true;
    for (StaticParam elt : that) {
